style.css:
@-moz-document domain("roblox.com") {
:root {
        --my-bg: #101010;
        --my-panel: rgba(17, 17, 17, 0.82);
        --my-detail: #858585;
        --my-text: #c5c5c5;
        --my-border: rgba(130, 130, 130, 0.2);
        --my-image: url("https://postimg.cc");
    }

    html,
    body,
    .dark-theme,
    .light-theme {
        background: var(--my-bg) !important;
        color: var(--my-text) !important;
        position: relative !important;
    }

    body::before {
        content: "";
        position: fixed;
        inset: 0;
        z-index: 0;
        pointer-events: none;
        background-image:
            linear-gradient(rgba(0, 0, 0, 0.42), rgba(0, 0, 0, 0.55)),
            var(--my-image);
        background-size: cover;
        background-position: center center;
        background-repeat: no-repeat;
    }

    #wrap,
    .container-main,
    .content,
    #rbx-body,
    .page-content,
    .section-content-off {
        position: relative;
        z-index: 1;
        background: transparent !important;
    }

    #header,
    .rbx-header,
    #navigation,
    .rbx-left-col {
        background: rgba(15, 15, 15, 0.88) !important;
        border-color: var(--my-border) !important;
        backdrop-filter: blur(6px);
    }

    .navbar-search .form-control,
    .input-field {
        background: rgba(30, 30, 30, 0.9) !important;
        border-color: var(--my-border) !important;
        color: var(--my-text) !important;
    }

    h1, h2, h3, h4, h5,
    .text-name,
    .game-card-name,
    .rbx-text-navbar-right,
    a {
        color: var(--my-text) !important;
    }

    .text-secondary,
    .text-label,
    .game-card-info {
        color: var(--my-detail) !important;
    }

    .btn-growth-lg,
    .btn-growth-md,
    .btn-growth-sm,
    .btn-primary-md,
    .btn-primary-lg {
        background-color: #4a4a4a !important;
        border-color: #666666 !important;
        color: #ffffff !important;
    }

    .btn-growth-lg:hover,
    .btn-growth-md:hover,
    .btn-growth-sm:hover {
        background-color: #666666 !important;
    }

    ::-webkit-scrollbar {
        width: 8px !important;
    }

    ::-webkit-scrollbar-thumb {
        background: #555555 !important;
        border-radius: 10px !important;
    }

    ::-webkit-scrollbar-track {
        background: #171717 !important;
    }

    ::selection {
        background: #666666 !important;
        color: #ffffff !important;
    }

    input[type="range"]::-webkit-slider-thumb {
        -webkit-appearance: none !important;
        appearance: none !important;
        background: transparent !important;
        background-image: url("https://postimg.cc") !important;
        background-size: contain !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
        width: 28px !important;
        height: 28px !important;
        border: none !important;
        cursor: pointer;
    }
}
